import org.eclipse.swt.SWT;
import org.eclipse.swt.events.SelectionAdapter;
import org.eclipse.swt.events.SelectionEvent;
import org.eclipse.swt.widgets.Composite;
import org.eclipse.swt.widgets.Link;
import org.eclipse.ui.IMarkerResolution;

public class TestClass {
    public void setupUI(Composite resolutionComposite, IMarkerResolution resolution) {
        Link resolutionLink = new Link(resolutionComposite, SWT.NONE);
        resolutionLink.setText("<A>" + resolution.getLabel() + "</a>"); // Target line
        resolutionLink.addSelectionListener(new SelectionAdapter() {
            @Override
            public void widgetSelected(SelectionEvent e) {
                System.out.println("Link clicked");
            }
        });
    }

    // Mock classes for compilation
    public static class MockMarkerResolution implements IMarkerResolution {
        @Override
        public String getLabel() { return "Fix & Apply"; }
        @Override
        public void run(org.eclipse.core.resources.IMarker marker) {}
    }

    // Mock for Eclipse IMarker (needed by IMarkerResolution.run)
    // This class won't actually be used, just needs to exist for compilation.
    public static class MockMarker implements org.eclipse.core.resources.IMarker {
        @Override public Object getAdapter(Class adapter) { return null; }
        @Override public boolean exists() { return false; }
        @Override public Object getAttribute(String attributeName) { return null; }
        @Override public int getAttribute(String attributeName, int defaultValue) { return defaultValue; }
