        @Override public boolean isSubtypeOf(String superType) { return false; }
        @Override public void delete() throws org.eclipse.core.runtime.CoreException { }
        @Override public void setAttribute(String attributeName, Object value) throws org.eclipse.core.runtime.CoreException { }
        @Override public void setAttributes(String[] attributeNames, Object[] values) throws org.eclipse.core.runtime.CoreException { }
        @Override public void setAttributes(java.util.Map attributes) throws org.eclipse.core.runtime.CoreException { }
    }
}

