import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.Composite;
import org.eclipse.swt.widgets.Label;
import org.eclipse.swt.widgets.Link;
import org.eclipse.ui.IMarkerResolution;

public class TestClass {
    public void noMatchCases(Composite parent, IMarkerResolution resolution) {
        // 1. Already handled
        Link link1 = new Link(parent, SWT.NONE);
        String text1 = resolution.getLabel().replace("&", "&&");
        link1.setText("<A>" + text1 + "</a>");

        // 2. Different string literal content
        Link link2 = new Link(parent, SWT.NONE);
        link2.setText("Some other <A>Text</A>");

        // 3. Not a Link widget (setText method is overloaded, but the pattern implicitly binds to Link.setText)
        Label label = new Label(parent, SWT.NONE);
        label.setText("<A>" + resolution.getLabel() + "</a>");

        // 4. Different structure, direct method call
        Link link4 = new Link(parent, SWT.NONE);
        link4.setText(resolution.getLabel());

        // 5. Different string literal structure
        Link link5 = new Link(parent, SWT.NONE);
        link5.setText(resolution.getLabel() + "<A>More</A>");
    }

